function ping(ac,dest,f,hz){const o=ac.createOscillator(),g=ac.createGain(),n=ac.currentTime;o.type=hz?'square':'sine';o.frequency.value=f;g.gain.setValueAtTime(0,n);g.gain.linearRampToValueAtTime(hz?.12:.22,n+.01);g.gain.exponentialRampToValueAtTime(.001,n+.16);o.connect(g);g.connect(dest);o.start(n);o.stop(n+.18);}
function stopAudio(){if(!AUD)return;clearInterval(AUD.iv);try{AUD.ac.close();}catch(e){}AUD=null;const b=$('#audBtn');if(b)b.textContent='Hear the scene (headphones)';}
function toggleAudio(o,btn){if(AUD){stopAudio();return;}if(!o||!o.st)return;const AC=window.AudioContext||window.webkitAudioContext;if(!AC){toast('Web Audio is not available in this browser.');return;}const ac=new AC(),master=ac.createGain();master.gain.value=.6;master.connect(ac.destination);
  const vs=o.st.o.map(ob=>{const p=ac.createPanner();p.panningModel='HRTF';p.distanceModel='inverse';p.refDistance=1.5;p.connect(master);return{ob,p,next:0};});
  AUD={ac,iv:setInterval(()=>{const now=ac.currentTime;for(const v of vs){const ob=v.ob;if(ob.z<1||ob.z>24)continue;if(v.p.positionX){v.p.positionX.value=ob.x;v.p.positionY.value=0;v.p.positionZ.value=-ob.z;}else v.p.setPosition(ob.x,0,-ob.z);if(now>=v.next){ping(ac,v.p,ob.f,ob.haz&&ob.z<10);v.next=now+clamp(ob.z/7,.16,1.3);}}},50)};btn.textContent='Stop audio';}

