const AQ=[{q:'Which depots logged the most idle hours last week?',u:'IDLE HOURS · LAST 7 DAYS',m:['metric question','3 tables · 2 joins','idle_hours · certified','3 of 3 agree','1.4 GB · $0.009','5 rows · checks pass','bar · 5 depots'],bars:[['N. YORK',412],['ETOBICOKE',356],['SCARB.',331],['VAUGHAN',264],['MISS.',219]],sql:"SELECT depot, SUM(idle_minutes) / 60 AS idle_hours\nFROM fleet.trips JOIN fleet.vehicles USING (vehicle_id)\nWHERE trip_start >= TIMESTAMP_SUB(CURRENT_TIMESTAMP(), INTERVAL 7 DAY)\nGROUP BY depot\nORDER BY idle_hours DESC\nLIMIT 5;"},
  {q:'How did harsh braking per 1,000 km change since May?',u:'HARSH BRAKES PER 1,000 KM',m:['metric question','2 tables · 1 join','harsh_brake_rate · certified','2 of 3 agree → judge','0.6 GB · $0.004','6 rows · checks pass','bar · 6 months'],bars:[['MAY',3.9],['JUN',3.6],['JUL',3.8],['AUG',3.1],['SEP',2.7],['OCT',2.4]],sql:"SELECT FORMAT_DATE('%b', event_date) AS month,\n       1000 * COUNTIF(event_type = 'HARSH_BRAKE') / SUM(km) AS per_1000_km\nFROM fleet.daily_vehicle_stats\nWHERE event_date >= '2026-05-01'\nGROUP BY month\nORDER BY MIN(event_date);"},
  {q:'Which vehicles are overdue for service by engine hours?',u:'ENGINE HOURS OVERDUE',m:['exploratory question','4 tables · 3 joins','no certified metric → SQL','3 of 3 agree','2.1 GB · $0.013','12 rows · null fix applied','ranked · top 5'],bars:[['V-1042',212],['V-0877',188],['V-1310',161],['V-0451',140],['V-1196',122]],sql:"SELECT v.vehicle_id,\n       (e.engine_hours - s.last_service_hours) - v.service_interval_hours AS hours_overdue\nFROM fleet.vehicles v\nJOIN fleet.engine_hours_latest e USING (vehicle_id)\nJOIN fleet.service_log_latest s USING (vehicle_id)\nWHERE (e.engine_hours - s.last_service_hours) > v.service_interval_hours\nORDER BY hours_overdue DESC;"}];
